"""Build the held-tree kernels with every scan generated by ``tree_scan``, for A/B records and timings.

:func:`install` replaces, before any held-tree kernel is built, the module
texts of the held tree's scans (``tree_kinetic_state``'s pose and motion
scans, subtree, interval and external reductions and twist publication, and
``tree_chain_scan``'s chain scans and reductions) with their ``tree_scan``
configurations, written with the layout's size names so that one text serves
every layout, on the plan structs the kernels already pass. Nothing else in
the kernels changes. ``record`` runs ``held_tree_ab.py record`` with the
replacement installed::

    python tools/fpgs_bench/tree_scan_dropin.py record generated.npz --device cuda:0
    python tools/fpgs_bench/held_tree_ab.py record existing.npz --device cuda:0
    python tools/fpgs_bench/held_tree_ab.py compare existing.npz generated.npz

``time`` times the finish, predictor and repair kernels of a held-tree owner on
replicated trees (``--shape``, ``--worlds``), both arms alternating in one process.
"""

import argparse
import sys
from pathlib import Path

sys.path.insert(0, str(Path(__file__).resolve().parents[2]))

from newton._src.solvers.feather_pgs import tree_chain_scan, tree_kinetic_state
from newton._src.solvers.feather_pgs import tree_scan as ts
from newton._src.solvers.feather_pgs.spatial_laws import SPATIAL
from newton._src.solvers.feather_pgs.tree_plan import TreePlan

_SIZES = {
    "nodes": "$BODIES",
    "rounds": "$ROUNDS",
    "max_depth": "($LAST_PARENT+1)",
    "windows": "$WINDOWS",
}
_POSE_SLOTS = ts.Storage({"pose": "s[7*({node})+({k})]"})
_MOTION_SLOTS = ts.Storage(
    {"velocity": "s[$MOTION+6*({node})+({k})]", "acceleration": "s[$MOTION+$SIX_BODIES+6*({node})+({k})]"}
)
_REDUCE_SLOTS = ts.Storage({"wrench": "s[$WRENCH+6*({node})+({k})]", "moment": "s[$MOMENT+13*({node})+({k})]"})
_EXTERNAL_SLOTS = ts.Storage({"wrench": "s[6*({node})+({k})]"})
_MOTION = ts.TWIST.with_zero_acceleration()
_REDUCE = ts.add(ts.Group("wrench", 6), ts.Group("moment", 13, "refresh"))
_EXTERNAL = ts.add(ts.Group("wrench", 6))
_TWIST_SUM = ts.add(ts.Group("twist", 6))
# The sizes are names, so any parent-first plan stands for the layout's tree.
_ANY = TreePlan.build([-1, 0])


def _spatial() -> str:
    prelude = SPATIAL.prelude()
    return "#if defined(__CUDA_ARCH__)\n" + prelude.source + "\n#else\n" + prelude.cpu + "\n#endif\n"


def _scan(combine, direction, schedule, storage, access, **options):
    return ts.tree_scan(
        _ANY, combine, direction, schedule, storage=storage, access=access, sizes=_SIZES, lanes="$LANES", **options
    )


def _down(combine, schedule, storage):
    """A held-tree down scan: a native body over ``address`` with the plan struct named ``p``."""
    scan = _scan(combine, ts.Direction.DOWN, schedule, storage, ts.PlanAccess().renamed("p"), level_csr=False)
    return _spatial() + "    float* s=reinterpret_cast<float*>(address);\n" + scan.text


def _reduction(combine, schedule, storage):
    """A held-tree reduction fragment: ``s``, ``lane``, ``stride`` and the plan struct ``plan`` in scope."""
    return _scan(combine, ts.Direction.UP, schedule, storage, ts.PlanAccess(), level_csr=False).text


_TWIST_SOURCE = (
    "{{const int first=ds+plan.body_dof_start.data[{node}],count=plan.body_dof_count.data[{node}];"
    "for(int d=0;d<count;++d){{const wp::spatial_vector axis=f.S.data[first+d];const float speed=f.vhat.data[first+d];"
    "for(int k=0;k<6;++k){value}[k]+=axis[k]*speed;}}}}"
)
_TWIST_SINK = (
    "{{wp::spatial_vector twist;for(int k=0;k<6;++k)twist[k]={value}[k];"
    "f.predicted_twist.data[p.joint_child.data[js+{node}]]=twist;}}"
)


def _twist_block():
    scan = _scan(
        _TWIST_SUM,
        ts.Direction.DOWN,
        ts.Schedule.JUMP_SHFL,
        None,
        ts.PlanAccess(),
        source=_TWIST_SOURCE,
        sink=_TWIST_SINK,
        cpu=False,
    )
    return (
        "\n#if defined(__CUDA_ARCH__)\n    if(f.publish_twists!=0) {\n        SYNC();\n" + scan.cuda + "    }\n#endif\n"
    )


def _chain_reduction(*, moments, layout=None):
    if moments:
        return _reduction(_REDUCE, ts.Schedule.HEAVY_CHAIN, _REDUCE_SLOTS)
    return _reduction(_EXTERNAL, ts.Schedule.HEAVY_CHAIN, _EXTERNAL_SLOTS)


def install():
    """Replace the held tree's scan texts by their ``tree_scan`` configurations (before any kernel is built)."""
    tree_kinetic_state._POSE = _down(ts.TRANSFORM, ts.Schedule.JUMP_SMEM, _POSE_SLOTS)
    tree_kinetic_state._MOTION = _down(_MOTION, ts.Schedule.JUMP_SMEM, _MOTION_SLOTS)
    tree_kinetic_state._POSE_SHFL = _down(ts.TRANSFORM, ts.Schedule.JUMP_SHFL, _POSE_SLOTS)
    tree_kinetic_state._MOTION_SHFL = _down(_MOTION, ts.Schedule.JUMP_SHFL, _MOTION_SLOTS)
    tree_kinetic_state._LEVEL_REDUCE = _reduction(_REDUCE, ts.Schedule.LEVEL, _REDUCE_SLOTS)
    tree_kinetic_state._INTERVAL_REDUCE = _reduction(_REDUCE, ts.Schedule.DFS_INTERVAL, _REDUCE_SLOTS)
    tree_kinetic_state._EXTERNAL_REDUCE = (
        "    if(nonzero) {\n" + _reduction(_EXTERNAL, ts.Schedule.LEVEL, _EXTERNAL_SLOTS) + "    }\n"
    )
    tree_kinetic_state._TWIST_BLOCK = _twist_block()
    tree_chain_scan._POSE = _down(ts.TRANSFORM, ts.Schedule.HEAVY_CHAIN, _POSE_SLOTS)
    tree_chain_scan._MOTION = _down(_MOTION, ts.Schedule.HEAVY_CHAIN, _MOTION_SLOTS)
    tree_chain_scan.reduction_source = _chain_reduction


def _rebuild_kernels(owner):
    """Rebind an owner's kernels after the scan texts changed: clear the factories' caches, then bind again."""
    for factory in (
        tree_kinetic_state.get_helpers,
        tree_kinetic_state.get_state_kernel,
        tree_kinetic_state.get_predictor_kernel,
        tree_kinetic_state.get_bank_kernel,
        tree_kinetic_state.get_classify_kernel,
    ):
        factory.cache_clear()
    owner._bind_kernels()


def time_owner(args):
    """Time the held tree's finish, predictor and repair kernels on replicated trees, both arms in one process.

    The arms alternate (existing, generated, existing, ...) over ``--rounds`` rounds on one owner and one
    state; each kernel's time is the median over its arm's rounds of the per-round medians.
    """
    import os  # noqa: PLC0415
    from unittest.mock import patch  # noqa: PLC0415

    import numpy as np  # noqa: PLC0415
    import warp as wp  # noqa: PLC0415

    import newton  # noqa: PLC0415
    from newton._src.solvers.feather_pgs.solver_feather_pgs import SolverFeatherPGS  # noqa: PLC0415
    from newton._src.solvers.feather_pgs.sparse_mass_matrix import _SparseMassMatrixPlan  # noqa: PLC0415
    from newton._src.solvers.feather_pgs.tree_kinetic_owner import TreeKineticState  # noqa: PLC0415
    from newton._src.solvers.feather_pgs.tree_kinetic_sparse import TreeSparseOperator  # noqa: PLC0415
    from newton.tests.feather_pgs_tree_scan_fixture import SHAPES  # noqa: PLC0415

    wp.init()
    device = wp.get_device(args.device)
    parents = SHAPES[args.shape]
    rng = np.random.default_rng(5)
    scene = newton.ModelBuilder()
    bodies, joints = [], []
    for index, parent in enumerate(parents):
        body = scene.add_link(mass=0.5 + index * 0.1, inertia=wp.mat33(np.diag([0.04, 0.05, 0.07])))
        bodies.append(body)
        anchor = wp.transform(wp.vec3(0.07, 0.03 * (index % 5), -0.08), wp.quat_identity())
        if index == 0:
            joint = scene.add_joint_free(body)
        else:
            joint = scene.add_joint_revolute(
                bodies[parent], body, axis=(0.0, 1.0, 0.0), parent_xform=anchor, armature=0.05
            )
        joints.append(joint)
    scene.add_articulation(joints)
    builder = newton.ModelBuilder()
    builder.replicate(scene, args.worlds)
    model = builder.finalize(device=device)
    options = {"pgs_mode": "split", "friction_anchor_beta": 0.0, "use_parallel_streams": False, "double_buffer": False}
    with patch.dict(os.environ, {"FEATHER_PGS_TREE_KINETIC_STATE": "0"}):
        solver = SolverFeatherPGS(model, **options)
    count = model.joint_dof_count // args.worlds
    mass = _SparseMassMatrixPlan.build(parents, np.diff(model.joint_qd_start.numpy())[: len(parents)])
    solver._sparse_mass_matrix_size = count
    solver._sparse_mass_matrix_plan = mass
    solver._sparse_mass_matrix_indices = mass.to_device(device)
    solver._sparse_Linv = wp.zeros((args.worlds, mass.nonzero_count), dtype=float, device=device)
    solver._sparse_mass_matrix_status = wp.zeros(args.worlds, dtype=int, device=device)
    solver._sparse_factor_warps_per_block = 4
    operator = TreeSparseOperator(solver)
    switches = {"FEATHER_PGS_TREE_CHAIN_SCAN": str(int(args.chains)), "FEATHER_PGS_TREE_LANE_PACK": str(args.lane_pack)}
    with patch.dict(os.environ, switches):
        owner = TreeKineticState(operator)
    operator.kinetic_state = owner
    state_in, state_out, control = model.state(), model.state(), model.control()
    state_in.joint_qd.assign(rng.uniform(-0.5, 0.5, model.joint_dof_count).astype(np.float32))
    state_in.body_f.assign(rng.normal(0, 0.1, (model.body_count, 6)).astype(np.float32))
    newton.eval_fk(model, state_in.joint_q, state_in.joint_qd, state_in)
    dt = 1.0 / 240.0
    solver._last_step_dt = dt
    augmented = solver._prepare_augmented_state(state_in, model.state(), control)

    def measure(call):
        times = []
        for _ in range(args.samples):
            start, end = wp.Event(device, enable_timing=True), wp.Event(device, enable_timing=True)
            wp.record_event(start)
            call()
            wp.record_event(end)
            wp.synchronize_event(end)
            times.append(wp.get_event_elapsed_time(start, end) * 1000.0)
        return float(np.median(times))

    def repair():
        owner.invalidate()
        owner.begin(state_in, augmented, state_in.joint_qd, dt, True)

    calls = {
        "finish_refresh_us": lambda: owner.finish(state_in, augmented, state_out, dt, True),
        "finish_us": lambda: owner.finish(state_in, augmented, state_out, dt, False),
        "predict_us": lambda: owner.predict(state_in, augmented, control, state_in.joint_qd, dt),
        "repair_us": repair,
    }
    arms = {"existing": {name: [] for name in calls}, "generated": {name: [] for name in calls}}
    built = {}
    texts = {name: getattr(tree_kinetic_state, name) for name in _HELD_TEXTS}
    chain_texts = {"_POSE": tree_chain_scan._POSE, "_MOTION": tree_chain_scan._MOTION}
    reduction = tree_chain_scan.reduction_source
    for round_index in range(args.rounds):
        for arm in ("existing", "generated"):
            if arm == "generated":
                install()
            else:
                for name, text in texts.items():
                    setattr(tree_kinetic_state, name, text)
                for name, text in chain_texts.items():
                    setattr(tree_chain_scan, name, text)
                tree_chain_scan.reduction_source = reduction
            _rebuild_kernels(owner)
            if round_index == 0:
                repair()
                for call in calls.values():
                    call()
                wp.synchronize_device(device)
                built[arm] = owner.finish_kernel.key
            for name, call in calls.items():
                arms[arm][name].append(measure(call))
    results = {
        "layout": f"bodies={owner.layout.bodies} lanes={owner.layout.lanes} chain={owner.chain_scan} block={owner.block_dim}"
    }
    for arm, values in arms.items():
        results[arm] = {name: float(np.median(v)) for name, v in values.items()}
    results["kernels"] = built
    print(results, flush=True)


_HELD_TEXTS = (
    "_POSE",
    "_MOTION",
    "_POSE_SHFL",
    "_MOTION_SHFL",
    "_LEVEL_REDUCE",
    "_INTERVAL_REDUCE",
    "_EXTERNAL_REDUCE",
    "_TWIST_BLOCK",
)


def main():
    parser = argparse.ArgumentParser(description=__doc__, formatter_class=argparse.RawDescriptionHelpFormatter)
    sub = parser.add_subparsers(dest="mode", required=True)
    record = sub.add_parser("record")
    record.add_argument("rest", nargs=argparse.REMAINDER)
    timing = sub.add_parser("time")
    timing.add_argument("--device", default="cuda:0")
    timing.add_argument("--shape", default="anymal13")
    timing.add_argument("--worlds", type=int, default=4096)
    timing.add_argument("--chains", type=int, default=0)
    timing.add_argument("--lane-pack", default="0")
    timing.add_argument("--samples", type=int, default=21)
    timing.add_argument("--rounds", type=int, default=3)
    args = parser.parse_args()
    if args.mode == "record":
        install()
        from tools.fpgs_bench import held_tree_ab  # noqa: PLC0415

        sys.argv = ["held_tree_ab.py", "record", *args.rest]
        held_tree_ab.main()
    else:
        time_owner(args)


if __name__ == "__main__":
    main()
